/*
 * prog47_circular_queue – reproduced from the original binary
 *
 * Behaviour (as observed from the decompiled state‑machine):
 *
 *   * Implements a circular queue of capacity 5 that stores signed 64‑bit
 *     integers (type `long` on the target platform).
 *
 *   * Processes each command‑line argument (argv[1] … argv[argc‑1]) in order.
 *
 *   * Commands:
 *
 *       E<number>   – enqueue the decimal number <number>.
 *                     If the queue is full, prints "FULL".
 *                     Otherwise stores the value and prints
 *                     "ENQ <value>\n".
 *
 *       D           – dequeue the element at the front.
 *                     If the queue is empty, prints "EMPTY".
 *                     Otherwise removes the element and prints
 *                     "DEQ <value>\n".
 *
 *       F           – print the element at the front (without removing).
 *                     If the queue is empty, prints "EMPTY".
 *                     Otherwise prints "FRONT <value>\n".
 *
 *   * Any other argument results in printing "ERR".
 *
 *   * If the program is invoked without any arguments (argc < 2) it prints
 *     a single line "NOOP" and exits.
 *
 *   * The queue is implemented with a static array `items[5]`,
 *     an index `head` (pointing to the current front) and a counter
 *     `count` (number of elements currently stored).  The tail index is
 *     derived as `(head + count) % 5`.
 *
 *   * All output uses `puts` for constant strings and `printf` for values,
 *     matching the exact order of messages produced by the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define QUEUE_CAP 5

int main(int argc, char **argv)
{
    /* No arguments – original program prints "NOOP". */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    long items[QUEUE_CAP];   /* circular buffer */
    int  head  = 0;          /* index of the front element */
    int  count = 0;          /* number of elements stored */

    for (int i = 1; i < argc; ++i) {
        char *cmd = argv[i];

        /* ENQUEUE – command starts with 'E' followed by a decimal number. */
        if (cmd[0] == 'E') {
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);

            /* No digits after the leading 'E' → error */
            if (endptr == cmd + 1) {
                puts("ERR");
                continue;
            }

            if (count == QUEUE_CAP) {
                puts("FULL");
                continue;
            }

            /* Store at tail = (head + count) % QUEUE_CAP */
            items[(head + count) % QUEUE_CAP] = val;
            ++count;
            printf("ENQ %ld\n", val);
            continue;
        }

        /* DEQUEUE – exactly the single character "D". */
        if (cmd[0] == 'D' && cmd[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }

            long val = items[head];
            head = (head + 1) % QUEUE_CAP;
            --count;
            printf("DEQ %ld\n", val);
            continue;
        }

        /* FRONT – exactly the single character "F". */
        if (cmd[0] == 'F' && cmd[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }

            long val = items[head];
            printf("FRONT %ld\n", val);
            continue;
        }

        /* Anything else is an error */
        puts("ERR");
    }

    return 0;
}
